-- Remove legacy shop/SureCart roles and caps from wp_user_roles.
-- Generated: 2026-06-24
-- Apply after deploying the Operations capability foundation.
-- This stores a one-time backup in wp_options before replacing wp_user_roles.
-- Removed roles: customer, shop_manager, sc_shop_manager, sc_shop_accountant, sc_shop_worker, sc_customer.

START TRANSACTION;

INSERT INTO wp_options (option_name, option_value, autoload)
SELECT 'wp_user_roles_backup_20260624_shop_surecart_cleanup', option_value, 'no'
FROM wp_options
WHERE option_name = 'wp_user_roles'
  AND NOT EXISTS (
    SELECT 1
    FROM (
      SELECT option_id
      FROM wp_options
      WHERE option_name = 'wp_user_roles_backup_20260624_shop_surecart_cleanup'
    ) AS existing_backup
  );

UPDATE wp_options
SET option_value = CONVERT( USING utf8mb4)
WHERE option_name = 'wp_user_roles';

COMMIT;
